const days = Number($('Config').first().json.replyWindowDays) || 14;
const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;

return ($input.first().json.data || [])
  .filter((p) => p.id)
  .filter((p) => !p.timestamp || new Date(p.timestamp).getTime() >= cutoff)
  .map((p) => ({ json: { postId: p.id, postText: p.text || '' } }));

// Whether a comment was already handled is read back from Threads rather than
// kept locally: /conversation returns the whole thread, and every reply of
// ours carries replied_to.
const posts = {};
for (const item of $('Filter posts').all()) {
  posts[item.json.postId] = item.json.postText;
}

// The only local state: comments the model declined to answer, so they are not
// sent to it again every hour. Losing this state costs nothing.
const store = $getWorkflowStaticData('global');
store.skipped = store.skipped || {};

const cfg = $('Config').first().json;
const maxPerRun = Number(cfg.maxRepliesPerRun) || 25;
const maxDepth = Number(cfg.maxThreadDepth) || 2;

const out = [];

for (const item of $input.all()) {
  const all = item.json.data || [];

  const byId = {};
  for (const r of all) if (r.id) byId[r.id] = r;

  const answered = new Set(
    all
      .filter((r) => r.is_reply_owned_by_me === true && r.replied_to && r.replied_to.id)
      .map((r) => r.replied_to.id),
  );

  // How many times we already spoke higher up this chain. Without a cap,
  // anyone who keeps replying can keep the account talking indefinitely.
  const ownRepliesAbove = (c) => {
    let n = 0;
    let cur = c;
    for (let hop = 0; hop < 50; hop++) {
      const parentId = cur.replied_to && cur.replied_to.id;
      cur = parentId ? byId[parentId] : null;
      if (!cur) break;
      if (cur.is_reply_owned_by_me === true) n += 1;
    }
    return n;
  };

  for (const c of all) {
    if (!c.id) continue;
    if (c.is_reply_owned_by_me === true) continue;
    if (c.hide_status === 'HIDDEN') continue;
    if (!c.text || !c.text.trim()) continue;
    if (answered.has(c.id)) continue;
    if (store.skipped[c.id]) continue;

    const depth = ownRepliesAbove(c);
    if (depth >= maxDepth) continue;

    const rootId = c.root_post && c.root_post.id ? c.root_post.id : null;

    out.push({
      json: {
        commentId: c.id,
        username: c.username || '',
        commentText: c.text.trim(),
        timestamp: c.timestamp || '',
        postText: rootId && posts[rootId] !== undefined ? posts[rootId] : '',
        lastInThread: depth === maxDepth - 1,
      },
    });
  }
}

// Oldest first, so nobody waits longer than anyone else.
out.sort(
  (a, b) =>
    new Date(a.json.timestamp || 0).getTime() - new Date(b.json.timestamp || 0).getTime(),
);

return out.slice(0, maxPerRun);

const cfg = $('Config').first().json;
const maxChars = Number(cfg.maxReplyChars) || 180;

const system = [
  cfg.playbook,
  '---',
  'YOUR TASK: write a reply to a comment on one of my posts.',
  'LIMITS:',
  `- No longer than ${maxChars} characters.`,
  '- No markdown. Return ONLY the reply text, without quotes.',
  '- Do not address the person with @, Threads already shows this is a reply.',
  '- If the playbook says this comment should not be answered, return exactly: SKIP',
].join('\n');

return $input.all().map((item) => {
  const content = [
    'MY POST:',
    item.json.postText || '(no text)',
    '',
    `COMMENT from @${item.json.username || 'unknown'}:`,
    item.json.commentText,
    '',
    'Write a reply to this comment.',
  ];

  if (item.json.lastInThread) {
    content.push(
      '',
      'This is the last reply I will send in this thread. Round it off: answer what was asked, point at the link in my profile if the person showed interest, and do not ask a question back.',
    );
  }

  return {
    json: {
      model: cfg.model,
      max_tokens: 2000,
      output_config: { effort: 'low' },
      fallbacks: 'default',
      system,
      messages: [{ role: 'user', content: content.join('\n') }],
    },
  };
});

// One model response per comment, in the same order as 'Select unanswered'.
const source = $('Select unanswered').all();
const maxChars = Number($('Config').first().json.maxReplyChars) || 180;

const store = $getWorkflowStaticData('global');
store.skipped = store.skipped || {};

const out = [];

$input.all().forEach((item, i) => {
  const res = item.json || {};
  const src = source[i] ? source[i].json : {};
  if (!src.commentId) return;

  // A failed or refused request is skipped silently and retried next run,
  // since no reply was posted to Threads either way.
  if (res.error || res.stop_reason === 'refusal') return;

  let text = (res.content || [])
    .filter((b) => b.type === 'text')
    .map((b) => b.text)
    .join('\n')
    .trim();

  if (!text) return;

  text = text
    .replace(/^```[a-z]*\n?|```$/gim, '')
    .replace(/^[\u0022\u00AB\u201C\u201E\u0027]+|[\u0022\u00BB\u201D\u2018\u0027]+$/g, '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .trim();

  if (/^SKIP\b/i.test(text)) {
    store.skipped[src.commentId] = new Date().toISOString();
    return;
  }

  if (text.length > maxChars) {
    const cut = text.slice(0, maxChars);
    const stop = Math.max(cut.lastIndexOf('.'), cut.lastIndexOf('!'), cut.lastIndexOf('?'));
    text = (stop > maxChars * 0.5 ? cut.slice(0, stop + 1) : cut).trim();
  }

  out.push({ json: { commentId: src.commentId, username: src.username, reply: text } });
});

const keys = Object.keys(store.skipped);
if (keys.length > 2000) {
  for (const k of keys.slice(0, keys.length - 2000)) delete store.skipped[k];
}

return out;
